window.ScripturaLexicons.BDAG_PART_0205 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-01\" data-source=\"BDAG\" data-search=\"κοιλία, ας, ἡ substantivo feminino ventre; estômago; útero; interior do ser humano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοιλία, ας, ἡ</td><td>substantivo feminino</td><td>ventre; estômago; útero; interior do ser humano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-02\" data-source=\"BDAG\" data-search=\"κοιμάω verbo dormir; adormecer; morrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοιμάω</td><td>verbo</td><td>dormir; adormecer; morrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-03\" data-source=\"BDAG\" data-search=\"κοίμησις, εως, ἡ substantivo feminino sono; adormecimento; morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοίμησις, εως, ἡ</td><td>substantivo feminino</td><td>sono; adormecimento; morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-04\" data-source=\"BDAG\" data-search=\"κοιμητήριον, ου, τό substantivo neutro dormitório; lugar de repouso; cemitério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοιμητήριον, ου, τό</td><td>substantivo neutro</td><td>dormitório; lugar de repouso; cemitério</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-05\" data-source=\"BDAG\" data-search=\"κοινῇ advérbio; remissão em comum; conjuntamente; veja κοινός 1c BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινῇ</td><td>advérbio; remissão</td><td>em comum; conjuntamente; veja κοινός 1c</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-06\" data-source=\"BDAG\" data-search=\"κοινός, ή, όν adjetivo comum; compartilhado; ordinário; profano; impuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινός, ή, όν</td><td>adjetivo</td><td>comum; compartilhado; ordinário; profano; impuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-07\" data-source=\"BDAG\" data-search=\"κοινόω verbo compartilhar; tornar comum ou impuro; profanar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινόω</td><td>verbo</td><td>compartilhar; tornar comum ou impuro; profanar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-08\" data-source=\"BDAG\" data-search=\"Κόϊντος, ου, ὁ nome próprio masculino Quinto, cristão de Esmirna BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κόϊντος, ου, ὁ</td><td>nome próprio masculino</td><td>Quinto, cristão de Esmirna</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-09\" data-source=\"BDAG\" data-search=\"κοινωνέω verbo participar; compartilhar; contribuir; tornar impuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινωνέω</td><td>verbo</td><td>participar; compartilhar; contribuir; tornar impuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-10\" data-source=\"BDAG\" data-search=\"κοινωνία, ας, ἡ substantivo feminino comunhão; associação; generosidade; contribuição; participação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινωνία, ας, ἡ</td><td>substantivo feminino</td><td>comunhão; associação; generosidade; contribuição; participação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-11\" data-source=\"BDAG\" data-search=\"κοινωνικός, ή, όν adjetivo generoso; liberal; disposto a compartilhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινωνικός, ή, όν</td><td>adjetivo</td><td>generoso; liberal; disposto a compartilhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-12\" data-source=\"BDAG\" data-search=\"κοινωνός, οῦ, ὁ substantivo masculino ou feminino participante; companheiro; associado; aquele que compartilha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινωνός, οῦ, ὁ</td><td>substantivo masculino ou feminino</td><td>participante; companheiro; associado; aquele que compartilha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-13\" data-source=\"BDAG\" data-search=\"κοινῶς advérbio na língua comum; no dialeto comum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινῶς</td><td>advérbio</td><td>na língua comum; no dialeto comum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-14\" data-source=\"BDAG\" data-search=\"κοινωφελής, ές adjetivo útil a todos; de benefício comum BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοινωφελής, ές</td><td>adjetivo</td><td>útil a todos; de benefício comum</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-15\" data-source=\"BDAG\" data-search=\"κοίτη, ης, ἡ substantivo feminino leito; cama conjugal; relação sexual; emissão seminal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοίτη, ης, ἡ</td><td>substantivo feminino</td><td>leito; cama conjugal; relação sexual; emissão seminal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-16\" data-source=\"BDAG\" data-search=\"κοιτών, ῶνος, ὁ substantivo masculino aposento; quarto de dormir; camareiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοιτών, ῶνος, ὁ</td><td>substantivo masculino</td><td>aposento; quarto de dormir; camareiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-17\" data-source=\"BDAG\" data-search=\"κοκκάριον, ου, τό substantivo neutro pequeno grão; grão de granizo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοκκάριον, ου, τό</td><td>substantivo neutro</td><td>pequeno grão; grão de granizo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-18\" data-source=\"BDAG\" data-search=\"κόκκινος, η, ον adjetivo escarlate; vermelho; tecido tingido de escarlate BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόκκινος, η, ον</td><td>adjetivo</td><td>escarlate; vermelho; tecido tingido de escarlate</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-19\" data-source=\"BDAG\" data-search=\"κόκκος, ου, ὁ substantivo masculino grão; semente; escarlate; matéria corante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόκκος, ου, ὁ</td><td>substantivo masculino</td><td>grão; semente; escarlate; matéria corante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0205-20\" data-source=\"BDAG\" data-search=\"κοκκύζω verbo cantar como galo; cacarejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοκκύζω</td><td>verbo</td><td>cantar como galo; cacarejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0205-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοιλία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοιλία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">κοῖλος</span> ‘oco’; Hdt., Aristoph. e posteriores; empréstimo no hebraico rabínico): no sentido mais amplo, a ‘cavidade’ do corpo (Gen 3:14, com <span class=\"greek\">στῆθος</span>), que abriga órgãos como o estômago, os intestinos e o útero, e, por extensão, referência a essas partes.</p>\n<p class=\"entry-text\">① Órgão de nutrição. ⓐ O trato digestivo em toda a sua extensão; ventre, barriga, estômago (Jer 28:34; Ezk 3:3; Sir 36:18 e outras passagens). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">χωρεῖν</span>, entrar no ventre (compare Plut., Mor. 699f <span class=\"greek\">εἴπερ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κοιλίαν</span> <span class=\"greek\">ἐχώρει</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">στομάχου</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πινόμενον</span>, se tudo quanto se bebe passa pela boca para o ventre. Até a porção final do canal alimentar é chamada <span class=\"greek\">κ</span>.: Herodian 1, 17, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:17</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:19</a>. ⓑ Especialmente, o receptáculo corporal dos alimentos; barriga, estômago (assim Diod S 2, 58, 3, entre <span class=\"greek\">φάρυγξ</span> [garganta] e <span class=\"greek\">σπλάγχνα</span> [intestinos]; Aelian, VH 1, 1 e outras passagens). Do estômago do peixe que engoliu Jonas (Jon 2:1f; Just., D. 107, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:40</a>. Do estômago humano, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:13</a>. <span class=\"greek\">γεμίσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, encher o estômago com algo, isto é, comer algo até ficar satisfeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:16</a>, variante de leitura. Quanto à ação de um pequeno rolo comido pelo autor do Apocalipse (compare Ezk 3:3), <span class=\"greek\">πικρανεῖ</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>., tornará amargo o teu estômago, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:9</a>; compare v. 10; <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κ</span>., ser escravo do próprio estômago, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:18</a>; <span class=\"greek\">ὧν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>., cujo deus é o próprio estômago, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:19</a>.</p>\n<p class=\"entry-text\">② Útero, ventre materno (Epict. 2, 16, 43; 3, 22, 74; Dt 28:4, 11; Job 1:21; Ruth 1:11; TestJob 24:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:41</a>, 44; 2:21; 11:27; 23:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:4</a>; B 13:2 (Gen 25:23). <span class=\"greek\">ἐκ</span> <span class=\"greek\">κοιλίας</span>, desde o nascimento, isto é, desde a mais tenra infância (Judg 16:17 A; Is 49:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:2</a>; 14:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:15</a>; <span class=\"greek\">καρπὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., fruto do ventre (compare Mi 6:7; La 2:20), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:42</a>.</p>\n<p class=\"entry-text\">③ Sede da vida interior, dos sentimentos e desejos; ventre (mas em inglês prefere-se o equivalente funcional ‘coração’): <span class=\"greek\">κ</span>. designa os recônditos ocultos e mais interiores do corpo humano (=<span class=\"hebrew\" dir=\"rtl\">טֶןבֶּ</span> Job 15:35; Pr 18:20; 20:27, 30; Sir 19:12; 51:21), de modo que se torna possível variar entre <span class=\"greek\">κοιλία</span> e <span class=\"greek\">καρδία</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>, variante de leitura (<span class=\"greek\">κοιλία</span> e <span class=\"greek\">καρδία</span> em lugar de <span class=\"greek\">ὀσφῦς</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:9</a> (variante <span class=\"greek\">καρδία</span>) (Hab 3:16; Ps 39:9; compare escólio a Nicander, Alexipharmaca 21 <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κοιλίας</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">καλοῦσιν</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δοχεῖον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντέρων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βρώσεως</span> [<span class=\"greek\">καρδία</span> designando a abertura superior do estômago: Theocr. 2, 49]; PGM 4, 3141: a <span class=\"greek\">κοιλία</span> é o lugar onde se encontra a <span class=\"greek\">καρδία</span>). <span class=\"greek\">ποταμοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ῥεύσουσιν</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ζῶντος</span>, rios de água viva fluirão do coração dessa pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:38</a> (considerado citação da Escritura, embora já não seja possível determinar com certeza a sua origem. A expressão pode ser proverbial; compare Cicero, De Orat. 2, 39 [162]. Frequentemente entendeu-se que <span class=\"greek\">κ</span>. se referia ao crente, mas cresce a tendência de pontuar com ponto-final depois de <span class=\"greek\">ἐμέ</span> no v. 38, e não depois de <span class=\"greek\">πινέτω</span>, no fim do v. 37 [veja margem da RSV e texto da NRSV], e entender <span class=\"greek\">κ</span>. como referência a Jesus; veja Hdb. ad loc.; JJeremias, Golgotha 1926, 80–84; HBornhäuser, Sukka ’35, 34–39; Bultmann, Ev. d. Joh. ’41, 228–30. Sobre a interpretação patrística, HRahner, Biblica 22, ’41, 269–302; 367–403. De modo diferente, A-MDubarle, Vivre et Penser 3, ’43/44, 238–41). JBlenkinsopp, NTS 6, ’59, 95–99.—B. 253. DELG s.v. <span class=\"greek\">κοῖλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοιμάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοιμάω</span> (veja os dois verbetes seguintes): imperativo médio do aoristo, 2ª pessoa do singular, <span class=\"greek\">κοιμήσαι</span> (TestAbr B 4, 109, 11 [Stone p. 66]). Na passiva: 1º futuro <span class=\"greek\">κοιμηθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐκοιμήθην</span>; perfeito <span class=\"greek\">κεκοίμημαι</span> (desde Hom.); em nossa literatura, somente na passiva e com sentido ativo.</p>\n<p class=\"entry-text\">① Estar dormindo, dormir, adormecer (uso habitual desde Hom.; Diod S 15, 25, 2; PGM 36, 151; 305; Jos., Bell. 4, 306, Ant. 8, 28, Vi. 132; Test12Patr, SibOr 3, 794), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a>; Hv 2, 4, 1; Hs 9, 11, 3; 6; <span class=\"greek\">φυλάκων</span> <span class=\"greek\">κοιμωμένων</span>, estando os guardas adormecidos, AcPl Ha 4, 4. Figuradamente, a respeito da noite (como a respeito do sol: Pythagoras em Geminus, Elementa Astronomiae p. 22e), <span class=\"greek\">κοιμᾶται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">νύξ</span>, a noite adormece, 1 Cl24:3.</p>\n<p class=\"entry-text\">② Estar morto, dormir; extensão figurada do sentido 1, para o sono da morte. Nesse uso, palavras adicionais frequentemente ressaltam a natureza figurada da expressão (já em Il. 11, 241; OGI 383, 43 [I a.C.]; IG XIV, 549, 1; 929, 13 <span class=\"greek\">κοιμᾶται</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">ὕπνον</span>, dorme o sono eterno). Entretanto, o verbo pode ter esse sentido mesmo sem tais acréscimos (Soph., Electra 509 <span class=\"greek\">Μυρτίλος</span> <span class=\"greek\">ἐκοιμάθη</span>; Aeschrion Lyr. [IV a.C.] 6, 2 Diehl2, epigrama sepulcral, <span class=\"greek\">ἐνταῦθα</span> <span class=\"greek\">κεκοίμημαι</span>; PFay 22, 28 [I a.C.] <span class=\"greek\">ἐὰν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span> <span class=\"greek\">κοιμήσηται</span>; Gen 47:30; Dt 31:16; 3 Km 11:43; Is 14:8; 43:17; 2 Macc 12:45.—OMerlier, BCH 54, 1930, 228–40; MOgle, The Sleep of Death: Memoirs of the Amer. Acad. in Rome 11, ’33, 81–117; JBowmer, ET 53, ’42, 355f [sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:20</a>, 22]; JKazakis, Hellenika 40, ’89, 21–33, motivos funerários. Veja <span class=\"greek\">ἐξυπνίζω</span>. New Docs 4, 37). ⓐ Adormecer, morrer, falecer (Did., Gen. 215, 20), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.60\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:60</a>; 13:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:39</a>; 11:30; 15:6, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:4</a>; 1 Cl 44:2; Hm 4, 4, 1. <span class=\"greek\">ἐκοιμήθην</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὕπνωσα</span> (Ps 3:6) é interpretado com o sentido de ‘morrer’ em 1 Cl 26:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span> <span class=\"greek\">ἐκοιμήθησαν</span>, adormeceram como justos, Hs 9, 16, 7. <span class=\"greek\">κοιμηθείς</span>, depois de minha morte, IRo 4:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">διδάσκαλοι</span> … <span class=\"greek\">κοιμηθέντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, os mestres que morreram no poder do Filho de Deus e na fé nele, Hs 9, 16, 5. <span class=\"greek\">οἱ</span> <span class=\"greek\">κοιμηθέντες</span>, os que já morreram, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:14f</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span>, os que morreram em comunhão com Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:18</a> (em contraste com Catullus 5, 6 nox est perpetua una dormienda = uma única noite eterna aguarda nosso sono). ⓑ O particípio presente e o particípio perfeito, com artigo e substantivados, designam um estado: os que adormeceram, <span class=\"greek\">οἱ</span> <span class=\"greek\">κοιμώμενοι</span> (2 Macc 12:45), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:13</a>; GPt 10:41.—<span class=\"greek\">οἱ</span> <span class=\"greek\">κεκοιμημένοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:20</a>; Hs 9, 16, 3.—Sem substantivação: <span class=\"greek\">οἱ</span> <span class=\"greek\">κεκοιμημένοι</span> <span class=\"greek\">ἅγιοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:52</a>; <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">κεκοιμημένοι</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ὄντες</span>, alguns estão mortos, outros ainda vivem, Hv 3, 5, 1.—B. 269. DELG s.v. <span class=\"greek\">κεῖμαι</span>. M-M s.v. <span class=\"greek\">κοιμάομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοίμησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοίμησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja o verbete precedente; Pla., inscrições, LXX).</p>\n<p class=\"entry-text\">① Estado de sono, ato de deitar-se para dormir, sono (Pla., Symp. 10 p. 183a). <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕπνου</span> (genitivo epexegético), o sono do adormecimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:13</a>. Veja New Docs 3, 93.</p>\n<p class=\"entry-text\">② Estado de morte, sono, extensão figurada do sentido 1 (Sir 46:19; 48:13; inscrições em sepulturas judaicas de Roma [ABerliner, Gesch. d. Juden in Rom I 1893, 72f; Schürer II 438, 45 <span class=\"greek\">ἐν</span> <span class=\"greek\">εἰρήνῃ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κοίμησις</span> <span class=\"greek\">αὐτοῦ</span>, em paz seja seu repouso; veja também CIJ]; Sb 1540, 5; IDefixWünsch 4, 30; Pel.-Leg. p. 15, 16; JosAs cap. 29, códice A, final; ApcMos 42), Hv 3, 11, 3; Hs 9, 15, 6.—FCumont, Le symbolisme funéraire des Romains ’42, 360–79.—DELG s.v. <span class=\"greek\">κεῖμαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοιμητήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοιμητήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja os dois verbetes precedentes) (IG VII, 235, 43 [IV a.C.]; Dosiadas Epigrammatist [III a.C.] em Athen. 4, 143c): quarto de dormir, lugar de repouso; no uso cristão (veja inscrições em New Docs 3, 138; 4, 234, inclusive judaicas), também campo-santo, cemitério. AcPl BMM verso 22 <span class=\"greek\">κο</span>[<span class=\"greek\">ι</span>]<span class=\"greek\">μητηρίων</span> (texto fragmentário, por isso o significado é incerto; mas, caso o contexto sugira perseguição, provavelmente se refere a ‘cemitério’).—DELG s.v. <span class=\"greek\">κεῖμαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινῇ</h1><div class=\"entry-meta\"><span>advérbio; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινῇ</span>: veja <span class=\"greek\">κοινός</span> 1c.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja os numerosos cognatos que seguem esta entrada; desde Hes.): originalmente ‘comum’ (oposto a <span class=\"greek\">ἴδιος</span>).</p>\n<p class=\"entry-text\">① Relativo àquilo que é de interesse mútuo ou coletivamente compartilhado; comunitário, comum (assim na literatura grega em geral, também LXX; EpArist, Philo, Joseph., SibOr). ⓐ Como adjetivo (<span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντων</span> <span class=\"greek\">πατήρ</span>, Orig., C. Cels. 8, 53, 27): <span class=\"greek\">τράπεζα</span>, mesa (Diod S 4, 74, 2), Dg 5:7a; <span class=\"greek\">πίστις</span>, fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:4</a>; <span class=\"greek\">σωτηρία</span>, salvação (compare SIG 409, 33f [cerca de 275 a.C.]; X., An. 3, 2, 32; Diod S 37, 2, 5; Polyaenus 5, 31), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 3</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">ἐλπίς</span>, esperança comum, IEph 21:2; IPhld 5:2; 11:2; <span class=\"greek\">κ</span>. <span class=\"greek\">ὄνομα</span>, nome comum (Philo, Abr. 7, Leg. ad Gai. 194), IEph 1:2; <span class=\"greek\">εἶχον</span> <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">κ</span>., tinham tudo em comum (<span class=\"greek\">κοινὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἔχειν</span>: Strabo 7, 3, 9.—Diod S 5, 9, 4: os habitantes de Lipara <span class=\"greek\">τὰς</span> <span class=\"greek\">οὐσίας</span> <span class=\"greek\">κοινὰς</span> <span class=\"greek\">ποιησάμενοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζῶντες</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">συσσίτια</span> = tornaram comuns seus bens e viviam segundo o costume das refeições comunitárias; Iambl., Vi. Pyth. 30, 168, dos pitagóricos: <span class=\"greek\">κοινὰ</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">πάντα</span> … <span class=\"greek\">ἦν</span>, <span class=\"greek\">ἴδιον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἐκέκτητο</span>, todas as coisas eram comuns a todos, e ninguém possuía nada de particular. Porphyr., Vi. Pyth. 20. A palavra ocorre em contexto semelhante referente aos essênios: Philo, Prob. Lib. 85; 86; Jos., Ant. 18, 20, e aos terapeutas: Philo, Vi. Cont. 32; 40; HBraun, Qumran u. d. NT, I, ’66, 43–50. Mesmo Pla., Phdr. 279c <span class=\"greek\">κοινὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φίλων</span>, comuns são os bens dos amigos), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:44</a>; compare 4:32 (compare 1QS 6:2; sobre a ideia recorrente do ‘outro eu’ na Antiguidade, veja também Persius, Satires 5, 22f; Horace, Odes 1, 3, 8; 2, 17, 5).—PSchmiedel, Die Gütergemeinschaft der ältesten Christenheit: PM 2, 1898, 367–78; EvDobschütz, Probleme des apost. Zeitalters 1904, 39ff; JBehm, Kommunismus im Urchristentum: NKZ 31, 1920, 275–97; KLake: Beginn. I/5, ’33, 140–51; Haenchen ad loc. (bibliografia). <span class=\"greek\">κοινῆς</span> <span class=\"greek\">εἰκαιότητος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπάτης</span>, de tolice e engano generalizados, Dg 4:6.—Quanto ao corpo e ao espírito: <span class=\"greek\">ἀμφότερα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐστιν</span>, ambos estão em comunhão = pertencem um ao outro, não podem ser separados, Hs 5, 7, 4.</p>\n<p class=\"entry-text\">ⓑ Substantivado: <span class=\"greek\">τὸ</span> <span class=\"greek\">κοινόν</span>, aquilo que é (mantido) em comum; <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span>, o fundamento comum da esperança, 1 Cl 51:1.—<span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>., a sociedade, a comunidade (para designar todos os integrantes de determinado grupo: POxy 53, 2 <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">τεκτόνων</span>, a associação dos carpinteiros; 84, 3; Jos., Vi. 65; Orig., C. Cels. 1, 31, 26; Hippol., Ref. 9, 19, 1), <span class=\"greek\">διακονία</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>., serviço prestado à comunidade (cristã), IPhld 1:1. Também o tesouro comum (Appian, Iber. 8, §31 <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. = tesouro público), dos escravos: <span class=\"greek\">ἐλευθεροῦσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., ser libertado à custa do tesouro comum (isto é, da comunidade cristã), IPol 4:3 (compare X., An. 4, 7, 27; 5, 1, 12 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κοινοῦ</span> = à custa do Estado; Jos., Vi. 297 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>.; 298).</p>\n<p class=\"entry-text\">ⓒ Como advérbio, <span class=\"greek\">κοινῇ</span>, conjuntamente, coletivamente (Soph., Thu. e posteriores; inscrições; PMagd 29, 2; LXX; Jos., C. Ap. 1, 70; 2, 166; Just., A I, 67, 5 e 7), IEph 20:2; ISm 12:2 (em ambos, em contraste com <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἄνδρα</span> [‘homem a homem’, ‘individualmente’], como em SIG 1073, 18); 7:2 (oposto a <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span>, como em Diod S 11, 24, 4; Dio Chrys. 34 [51], 9; SIG 630, 15 [leitura restaurada]; 2 Macc 9:26). <span class=\"greek\">τὸ</span> <span class=\"greek\">κοινῇ</span> <span class=\"greek\">συμφέρον</span>, o bem comum, B 4:10.</p>\n<p class=\"entry-text\">② Relativo ao que possui pouco valor por ser comum; comum, ordinário, profano. ⓐ Em sentido geral (compare Alcman [VII a.C.], Fgm. 49 D.2 <span class=\"greek\">τὰ</span> <span class=\"greek\">κοινά</span>, aquilo que as pessoas comuns comem, em contraste com pessoas de gostos refinados; Plut., Mor. 751b <span class=\"greek\">καλὸν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φιλία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀστεῖον</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἡδονὴ</span> <span class=\"greek\">κοινὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνελεύθερον</span> [Ltzm., Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:14</a>]; compare 1 Macc 1:47, 62; EpArist 315 = Jos., Ant. 12, 112 <span class=\"greek\">κοινοὶ</span> <span class=\"greek\">ἄνθρωποι</span>; 13, 4; Iren. 4, 18, 5 [Harv. II 206, 11]). <span class=\"greek\">κ</span>. <span class=\"greek\">ἡγεῖσθαί</span> <span class=\"greek\">τι</span>, considerar alguma coisa ordinária, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a>, a não ser que pertença a 2b. ⓑ Especificamente, daquilo que é cerimonialmente impuro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:27</a>; <span class=\"greek\">χεῖρες</span>, mãos (cerimonialmente) impuras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:2</a>, 5 (MSmith, Tannaitic Parall. to the Gosp. ’51, 31f); <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δι</span>’ <span class=\"greek\">ἑαυτοῦ</span>, nada é impuro por si mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:14a</a>; compare as alíneas b e c do mesmo versículo. <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">ἔφαγον</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀκάθαρτον</span>, jamais comi coisa alguma comum ou impura (1 Macc 1:62), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:14</a>; compare v. 28; 11:8 (CHouse, Andrews University Seminary Studies 21, ’83, 143–53); GJs 6:1 (veja deStrycker). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a>, veja 2a.—Dg 5:7b (veja <span class=\"greek\">κοίτη</span> 1b).—B. 1365. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινόω</span>: 1º aoristo <span class=\"greek\">ἐκοίνωσα</span>; perfeito <span class=\"greek\">κεκοίνωκα</span>; particípio passivo <span class=\"greek\">κεκοινωμένος</span> (Pind., Thu. e outros no sentido de <span class=\"greek\">κοινός</span> 1, ‘fazer alguém participar de alguma coisa’, ‘partilhar’; Jos., Ant. 5, 267; 18, 231; Iren.1, 2, 2 [Harv. I 15, 1]; quanto a inscrições, veja 1 abaixo).</p>\n<p class=\"entry-text\">① Compartilhar (Aeschyl., Suppl. 369; Thu. 2, 73, 1; Alciphron 3, 36, 4), na voz média. Paulo compartilhou com eles a mensagem (cristã) e disse, AcPl Ha 9, 32 [<span class=\"greek\">Παῦλος</span>] <span class=\"greek\">κο̣ι̣νω</span>[<span class=\"greek\">σά</span>|<span class=\"greek\">μενος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">εἶπεν</span>] (reconstruído segundo Aa I 114, 4; compare I 112, 4; compare IEph Ia, 25, 8, sobre informação comunicada [New Docs 4, 9]).</p>\n<p class=\"entry-text\">② Mais frequentemente, no sentido de <span class=\"greek\">κοινός</span> 2: tornar comum ou impuro; contaminar, profanar no sentido cultual (4 Macc 7:6; compare John Malalas [VI d.C.], Chronographia 277, 2 LDind. [1831] <span class=\"greek\">κοινώσας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕδατα</span>). ⓐ Com <span class=\"greek\">τινά</span>, alguém: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:11</a>, 18, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:15</a>, 18, 20, 23. Aoristo passivo, 3ª pessoa do plural, <span class=\"greek\">ἐκοινώθησαν</span> (AssMos Fgm. g); particípio perfeito passivo com artigo, substantivado, <span class=\"greek\">οἱ</span> <span class=\"greek\">κεκοινωμένοι</span>, os que estão contaminados, isto é, segundo a ordenança levítica, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:13</a>. ⓑ Com <span class=\"greek\">τὶ</span>, alguma coisa: tornar profano, profanar o templo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:28</a>. Na passiva, de um sacrifício que se tornou impuro, D 14:2. ⓒ Absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:27</a>, variante de leitura (em lugar de <span class=\"greek\">κοινόν</span>).</p>\n<p class=\"entry-text\">③ Considerar ou declarar (ritualmente) impuro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:15</a>; 11:9.—Sobre a perspectiva judaica, veja WPascher, Rein u. Unrein ’70, 165–68; compare Jos., Ant. 11, 8, 7.—DELG s.v. <span class=\"greek\">κοινός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κόϊντος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κόϊντος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Diod S 11, 27, 1, acerca de um contemporâneo da batalha de Salamina [480 a.C.]; Plut. e outros; SIG2 588, 34; SIG 1127, 3; OGI 684, 1; papiros [Preisigke, Namenbuch]; 2 Macc 11:34; Jos., Ant. 14, 219): Quinto, cristão de Esmirna, MPol 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινωνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινωνέω</span> (veja <span class=\"greek\">κοινός</span> e seus cognatos): futuro <span class=\"greek\">κοινωνήσω</span>; 1º aoristo <span class=\"greek\">ἐκοινώνησα</span>; perfeito <span class=\"greek\">κεκοινώνηκα</span> (desde Aeschyl.).</p>\n<p class=\"entry-text\">① Compartilhar, ter parte. ⓐ Com genitivo, <span class=\"greek\">τινός</span>, participar de alguma coisa (X., Rep. Lac. 1, 9, Mem. 2, 6, 23; Pla., Leg. 12 p. 947a; Diod S 5, 49, 6 <span class=\"greek\">τοὺς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">κοινωνήσαντας</span> = aqueles que participaram, isto é, foram iniciados nos mistérios; 5, 68, 3 <span class=\"greek\">τῆς</span> <span class=\"greek\">τροφῆς</span> <span class=\"greek\">ταύτης</span>; 15, 68, 1; 19, 4, 3; Herodian 3, 10, 8; inscrições [Kl. T. 121 no. 32, 41]; papiros; Pr 1:11; 3 Macc 2:31; Philo, Post. Cai. 160 e outras passagens; Jos., Ant. 4, 75, C. Ap. 2, 174; <span class=\"greek\">ὁ</span> <span class=\"greek\">μιλίας</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἑστίας</span> Just., D. 47, 2; <span class=\"greek\">τραπέζης</span> Orig., C. Cels. 2, 21, 6 e 17; <span class=\"greek\">αἰσθήσεως</span> Did., Gen. 149, 2.—B-D-F §169, 1; Rob. 509f). De seres humanos: <span class=\"greek\">αἵματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σαρκός</span>, participar da carne e do sangue, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a> (inscrição da Comagena em IReisenKN, Humann-Puchstein p. 371, 46–47 [I a.C.] <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ὅσοι</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">κοινωνοῦντες</span> <span class=\"greek\">ἀνθρωπίνης</span>).</p>\n<p class=\"entry-text\">ⓑ Com dativo, <span class=\"greek\">τινί</span>, participar de alguma coisa (Demosth., Prooem. 25, 2 [passagem posta entre colchetes por Blass]; Plut., 1030 [Arat. 8, 3]; Just., D. 35, 6; Tat. 19, 2; <span class=\"greek\">τῷ</span> <span class=\"greek\">θανάτῳ</span> Did., Gen. 148, 25; mas Wsd 6:23 [veja JCampbell, JBL 51, ’32, 359], ‘associar-se a’, assim NRSV; diferentemente REB). <span class=\"greek\">α</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">πνευματικοῖς</span>, participar dos bens espirituais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:27</a>; <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">παθήμασιν</span>, dos sofrimentos de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:13</a> (compare Achilles Tat. 7, 2, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παθεῖν</span> <span class=\"greek\">κοινωνία</span> = comunhão no sofrimento).</p>\n<p class=\"entry-text\">Quanto ao corpo de um mártir: receber uma parte dele, isto é, uma parte do corpo como ‘relíquia’, <span class=\"greek\">κ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἁγίῳ</span> <span class=\"greek\">σαρκίῳ</span>, MPol 17:1.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Participar das ações alheias significa ser igualmente responsável por elas: <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">ἀλλοτρίαις</span>, de pecados alheios, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:22</a> (Artem. 3, 51 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτημάτων</span> <span class=\"greek\">ἐκείνῳ</span>; Ath., R. 21 p. 73, 27 [do corpo] <span class=\"greek\">κ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">τῶν</span> … <span class=\"greek\">πόνων</span>); <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πονηροῖς</span>, de suas más obras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2J 11</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. A participação em algo pode chegar a tal ponto que a pessoa reivindique uma parte disso para si: interessar-se por, compartilhar (Philostrat., Vi. Apoll. 5, 25; Pr 1:11); <span class=\"greek\">ταῖς</span> <span class=\"greek\">χρείαις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span>, das necessidades dos santos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:13</a>. Com dativo de pessoa seguido de infinitivo: <span class=\"greek\">ἐκοινώνησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀρτέμων</span> … <span class=\"greek\">Παύλῳ</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">χά</span>[<span class=\"greek\">ριτι</span> <span class=\"greek\">θεοῦ</span>] <span class=\"greek\">δόξαι</span> (erro em lugar de <span class=\"greek\">δοξάσαι</span>) <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, Artemão associou-se a Paulo para louvar o Senhor, na graça de Deus, AcPl Ha 7, 22. A passagem para o sentido seguinte é natural.</p>\n<p class=\"entry-text\">② Dar ou contribuir com uma parte (Philo, Spec. Leg. 2, 107), com dativo de pessoa (compare Demosth. 25, 61; Appian, Bell. Civ. 1, 31 §139; Artem. 5 p. 252, 14; Sextus 350; Jos., C. Ap. 2, 258; Just. A I, 14, 2), seguido de <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>: conceder a alguém parte de alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:6</a>. <span class=\"greek\">κοινωνήσεις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">σου</span>, compartilharás todas as coisas com teu próximo, B 19:8. Também <span class=\"greek\">τινὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (compare Pla., Rep. 453a; PLond V, 1794, 7; TestZeb 3:1): <span class=\"greek\">οὐδεμία</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">ἐκοινώνησεν</span> <span class=\"greek\">εἰς</span>, nenhuma congregação se associou a mim para participar de, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:15</a>. Com acusativo de pessoa: <span class=\"greek\">κοινωνῆσαί</span> <span class=\"greek\">με</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἁμαρτίᾳ</span> <span class=\"greek\">σου</span>, fazer-me cúmplice de teu pecado, GJs 2:3 (veja deStrycker p. 306f).</p>\n<p class=\"entry-text\">③ Tornar (ritualmente) impuro, contaminar. O manuscrito D emprega <span class=\"greek\">κ</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:11</a> (duas vezes), 18, 20, no sentido de <span class=\"greek\">κοινόω</span> 2 (compare Diod S 5, 33, 5 <span class=\"greek\">κ</span>. = participar [de prática insalubre]).—DELG s.v. <span class=\"greek\">κοινός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινωνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινωνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete precedente; desde Pind.; inscrições, papiros, LXX; JosAs 7:6 códice A; Philo [Mos. 1, 158, acerca da comunhão com Deus]; Joseph.; empréstimo no hebraico rabínico; Just.; Tat. 18, 2; Ath.; Iren. 4, 18, 5 [Harv. II 205, 4], juntamente com <span class=\"greek\">ἕνωσις</span>).</p>\n<p class=\"entry-text\">① Associação estreita, que envolve interesses recíprocos e compartilhamento; associação, comunhão, fraternidade, relação estreita (daí ser expressão favorita para o vínculo conjugal, o mais íntimo dos relacionamentos humanos: Isocr. 3, 40; BGU 1051, 9 [I d.C.]; 1052, 7; POxy 1473, 33; 3 Macc 4:6; Jos., Ant. 1, 304; Did., Gen 235, 18. Mas veja também Diod S 10, 8, 2 <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">κ</span>. = o modo comum ou vínculo de vida que une os pitagóricos). Com genitivo, <span class=\"greek\">τινός</span>, com alguém ou em relação a alguém (Amphis Com. [IV a.C.] 20, 3; Herodian 1, 10, 1; <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Orig., C. Cels. 3, 56, 6). Portanto, há fundamento linguístico para traduzir <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span> por ‘comunhão com o Filho de Deus’, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:9</a> (veja 4 abaixo), e <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πνεύματος</span> por ‘comunhão com o Espírito Santo’, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:13</a> (assim JSickenberger, comentário [Bonnerbibel 1919; 4th ed. ’32], ad loc., em sentido trinitário; mas veja WKümmel, apêndice ao comentário de HLtzm. [Hdb]). Outros tomam este último genitivo como subjetivo ou como genitivo de qualidade: comunhão produzida pelo Espírito Santo (APlummer, com reservas, comentário a 2 Cor [ICC] e outros; TSchmidt, D. Leib Christi 1919, 135; veja 4 abaixo). Correspondentemente, <span class=\"greek\">κ</span>. <span class=\"greek\">πνεύματος</span>, comunhão com o Espírito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:1</a> (Synes., Prov. 1, 15 p. 108c <span class=\"greek\">κ</span>. <span class=\"greek\">γνώμης</span> = comunhão de vontade; veja 2 abaixo).</p>\n<p class=\"entry-text\"><span class=\"greek\">κοινωνία</span>(<span class=\"greek\">ν</span> <span class=\"greek\">ἔχειν</span>) <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, (ter) comunhão com alguém (compare Job 34:8): com Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:3b</a>, 6 (compare Epict. 2, 19, 27 <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Δία</span> <span class=\"greek\">κοινωνίας</span> <span class=\"greek\">βουλευόμενον</span>; Jos., Bell. 7, 264, C. Ap. 1, 35 [ambos com <span class=\"greek\">πρός</span> e acusativo]); com outros cristãos, vv. 3a, 7. Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (POxf 5f): <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, relação estreita com o evangelho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:5</a>. <span class=\"greek\">ηὐδόκησαν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ποιήσασθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πτωχούς</span>, dispuseram-se a estabelecer relação bastante estreita com os pobres, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:26</a> (de modo semelhante GPeterman, Make a Contribution or Establish Fellowship: NTS 40, ’94, 457–63; outros, porém, preferem o sentido 3 abaixo).</p>\n<p class=\"entry-text\"><span class=\"greek\">κ</span>. <span class=\"greek\">πρός</span> com acusativo, ligação com, relação com (Pla., Symp. 188c; Galen, Protr. 9 p. 28, 7 J.; SIG 646, 54 [170 a.C.]; Philo, Leg. ad Gai. 110 <span class=\"greek\">τίς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">κοινωνία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Ἀπόλλωνα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">οἰκεῖον</span> <span class=\"greek\">ἐπιτετηδευκότι</span>; compare Jos., C. Ap. 2, 208; <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">κ</span>., Ath. 12, 2; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θειότερον</span> <span class=\"greek\">κ</span>., Orig., C. Cels. 3, 28, 47): <span class=\"greek\">τίς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φωτὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σκότος</span>;, que comunhão tem a luz com as trevas?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:14</a> (compare Sir 13:2, 17f; Aristoph., Thes. 140 <span class=\"greek\">τίς</span> <span class=\"greek\">κατόπτρου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ξίφους</span> <span class=\"greek\">κοινωνία</span>;).</p>\n<p class=\"entry-text\">Sem complemento: comunhão, unidade (harmoniosa) (Hippol., Ref. 9, 12, 26), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:42</a> (veja JFitzmyer, PSchubert Festschr. ’66, 242–44 [Atos–Qumran], que sugere poder tratar-se aqui de ‘comunidade de bens’ [<span class=\"hebrew\" dir=\"rtl\">יחד</span>], como em 1QS 1, 11–13; 6, 17. Sobre a questão desse termo, veja HBraun, Qumran u. d. NT, I, ’66; 143–50; veja também ACarr, The Fellowship of <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:42</a> and Cognate Words: Exp. 8th ser., 5, 1913, 458ff). <span class=\"greek\">δεξιὰς</span> <span class=\"greek\">κοινωνίας</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινί</span>, dar a alguém a destra de comunhão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:9</a> (JSampley, Pauline Partnership in Christ ’80, defende uma noção jurídica de ‘consensual societas’, mas veja New Docs 3, 19).</p>\n<p class=\"entry-text\"><span class=\"greek\">κ</span>. tem também o sentido concreto de sociedade, fraternidade, enquanto maioria estreitamente unida, que naturalmente forma um todo: Maximus Tyr. 15, 4b <span class=\"greek\">τί</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κοινωνίας</span> <span class=\"greek\">συμβόλαιον</span>;, qual é a contribuição (isto é, do filósofo) à comunidade ou à sociedade (humana)?; 16, 2m <span class=\"greek\">δημώδεις</span> <span class=\"greek\">κοινωνίαι</span> = reuniões do povo comum.—Sobre clubes e associações antigos, veja Poland; também JWaltzing, Étude historique sur les corporations professionnelles chez les Romaine, 4 vols. 1895–1900; EZiebarth, Das griechische Vereinswesen 1896.</p>\n<p class=\"entry-text\">② Atitude de boa vontade que manifesta interesse em uma relação estreita; generosidade, solidariedade, altruísmo (Epict. em Stob. 43 Sch. <span class=\"greek\">χρηστότητι</span> <span class=\"greek\">κοινωνίας</span>; Arrian, Anab. 7, 11, 9 <span class=\"greek\">κ</span>. ao lado de <span class=\"greek\">ὁμόνοια</span>; Herm. Wr. 13, 9 [oposto a <span class=\"greek\">πλεονεξία</span>]): <span class=\"greek\">ἁπλότης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, generosidade da comunhão para com alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:13</a>. Com <span class=\"greek\">εὐποιί̈α</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:16</a>. O contexto também permite esse sentido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:1</a> (veja 1 acima). A transição para o sentido seguinte é natural.</p>\n<p class=\"entry-text\">③ Abstrato em lugar de um sinal concreto de comunhão: prova da unidade fraterna, até mesmo dádiva, contribuição (Lev 5:21; inscrições da Ásia Menor: <span class=\"greek\">κ</span>. = ‘subsídio’ [Rdm.2 10]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:26</a> (veja 1 acima). Sob esta rubrica talvez se deva classificar <span class=\"greek\">κοινωνία</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἵματος</span> (<span class=\"greek\">σώματος</span>) <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, meio para alcançar uma relação estreita com o sangue (corpo) de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16ab</a> (veja 4 abaixo).</p>\n<p class=\"entry-text\">④ Participação, compartilhamento, com genitivo, <span class=\"greek\">τινός</span>, de alguma coisa (Appian, Bell. Civ. 1, 67 §306 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">παρόντων</span> = participação nas atividades presentes; 5, 71 §299 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρχῆς</span>, no governo; Polyaenus 6, 7, 2 <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μιάσματος</span>, no ato torpe; Maximus Tyr. 19, 3b <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρετῆς</span>; Synes., Kgdm. 13 p. 12c <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span> = nas ações de outras pessoas; Wsd 8:18; Jos., Ant. 2, 62): <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεώς</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐνεργὴς</span> <span class=\"greek\">γένηται</span>, para que tua participação na fé se torne manifesta por tuas ações, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 6</a>. <span class=\"greek\">γνῶναι</span> <span class=\"greek\">κοινωνίαν</span> <span class=\"greek\">παθημάτων</span> <span class=\"greek\">αὐτοῦ</span>, conhecer a participação em seus sofrimentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:10</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">διακονίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἁγίους</span>, participar da assistência prestada ao povo de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:4</a>. Talvez caibam aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:9</a> (veja 1 acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:13</a> (participação no Espírito Santo: Ltzm., Kümmel no apêndice ao comentário de Ltzm., Windisch, Seesemann [veja abaixo] 70; Goodsp., Probs. 169f; veja 1 acima.—Compare <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">κ</span>., da experiência extática, Did., Gen. 230, 16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a> (participação no sangue [corpo] de Cristo. Assim ASchlatter, Pls der Bote Jesu ’34, 295f e outros; veja 3 acima. Mas talvez <span class=\"greek\">κοινωνία</span> com genitivo signifique aqui a posse ou fruição comum de algo [Diod S 8, 5, 1 <span class=\"greek\">ἀγελῶν</span> <span class=\"greek\">κ</span>. = dos rebanhos; Maximus Tyr. 19, 3b <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κοινωνίᾳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρετῆς</span> = para a posse comum da excelência; Diog. L. 7, 124; Synes., Kgdm. 20 p. 24b; Hierocles 6, 428: devemos escolher o melhor homem como amigo e unir-nos a ele <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρετῶν</span> <span class=\"greek\">κοινωνίαν</span> = para a posse ou fruição comum das virtudes; 7, 429 <span class=\"greek\">τῶν</span> <span class=\"greek\">καλῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>.]. Nesse caso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a> significaria: ‘Não representam o cálice e o pão a participação comum no corpo e no sangue de Cristo?’ Afinal, todos participamos do mesmo pão). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:9</a>, variante de leitura (em lugar de <span class=\"greek\">οἰκονομία</span>).—JCampbell, <span class=\"greek\">Κοινωνία</span> and Its Cognates in the NT: JBL 51, ’32, 352–80; EGroenewald, <span class=\"greek\">Κοινωνία</span> (gemeenskap) bij Pls, dissertação, Amst. ’32; HSeesemann, D. Begriff <span class=\"greek\">Κοινωνία</span> im NT ’33; PEndenburg, Koinoonia … bij de Grieken in den klass. tijd ’37; HFord, The NT Conception of Fellowship: Shane Quarterly 6, ’45, 188–215; GJourdan, <span class=\"greek\">Κοινωνία</span> in <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a>: JBL 67, ’48, 111–24; KNickle, The Collection, A Study in Paul’s Strategy, ’66.—EDNT, bibliografia adicional. Veja também RAC IX 1100–1145.—DELG s.v. <span class=\"greek\">κοινός</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινωνικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινωνικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">κοινωνία</span> e cognatos; desde Ps.-Pla., Def., e Aristot.; Vett. Val., papiros, Philo; Jos., Bell. 2, 122): relativo à disposição de dar ou compartilhar os próprios bens, liberal, generoso (Aristot., Rhet. 2, 24, 2: 1401a, 20; Polyb. 2, 44, 1; Lucian, Tim. 56 <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὄντων</span> <span class=\"greek\">κοινωνικός</span>, homem disposto a compartilhar seus bens; Iambl., Protr. 21, 19 [p. 117, 8]; 30 [123, 6]), com <span class=\"greek\">εὐμετάδοτος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:18</a>.—DELG s.v. <span class=\"greek\">κοινός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινωνός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino ou feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινωνός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> e <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κοινός</span> e seus cognatos; autores trágicos e outros; inscrições, papiros, LXX, Philo, Joseph., Just.).</p>\n<p class=\"entry-text\">① Pessoa que participa de alguma coisa juntamente com outra; companheiro, parceiro, participante.</p>\n<p class=\"entry-text\">ⓐ Com alguém, expresso <span class=\"greek\">α</span>. pelo dativo (Philo, Spec. Leg. 1, 131 <span class=\"greek\">θεῷ</span> <span class=\"greek\">τινος</span> [‘em alguma coisa’]; Jos., Ant. 8, 239 <span class=\"greek\">σοί</span> <span class=\"greek\">τινος</span>; Himerius, Or. 48 [=Or. 14], 15 <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκείνοις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώμης</span> = com aqueles homens [os sete sábios] no conhecimento): <span class=\"greek\">ἦσαν</span> <span class=\"greek\">κοινωνοὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Σίμωνι</span>, eram sócios (nos negócios) de Simão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:10</a> (aqui não é termo técnico, mas compare PAmh 100, 4: Hermes, pescador, toma Cornelius como seu <span class=\"greek\">κ</span>. = sócio; semelhantemente Diod S 8, 5, 3 <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. = sócio; BGU 1123, 4; veja New Docs 1, 85; 3, 19).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Pelo genitivo (Pr 28:24; Is 1:23; Mal 2:14; Orig., C. Cels. 3, 69, 33): <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἀναστρεφομένων</span> <span class=\"greek\">γενηθέντες</span>, tendo-se tornado companheiros daqueles que assim eram tratados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:33</a>. De um mártir (que compartilha com Cristo a morte sangrenta), <span class=\"greek\">Χριστοῦ</span>, MPol 6:2; compare 17:3. <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμονίων</span>, ser participante com as divindades (dos politeístas), nos sacrifícios que lhes são oferecidos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:20</a> (<span class=\"greek\">κ</span>. <span class=\"greek\">τραπέζης</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμονίων</span>, Orig., C. Cels. 8, 24, 32.—HGressmann, <span class=\"greek\">῾Η</span> <span class=\"greek\">κοινωνία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμονίων</span>: ZNW 20, 1921, 224–30; Clemen2 182–88).</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. Por <span class=\"greek\">μετά</span> com genitivo: <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">κ</span>., Hs 5, 6, 6.</p>\n<p class=\"entry-text\">ⓑ Em alguma coisa, expresso <span class=\"greek\">α</span>. pelo genitivo da coisa (Diod S 14, 61, 5; Epict. 3, 22, 63 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> [do cínico]; Plut., Mor. 45e; 819c, Brut. 13, 5; Aelian, VH 2, 24; Appian, Samn. 10 §12 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγαθῶν</span>; Maximus Tyr. 31, 5c; Sir 6:10; Esth 8:12n; Jos., Vi. 142, Ant. 4, 177 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ταλαιπωρίας</span>; Just., A II, 2, 6 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀδικημάτων</span>): <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυσιαστηρίου</span>, participante do altar, 1 Cor 10:l8 (Pla., Ep. 7, 350c <span class=\"greek\">κοινωνὸς</span> <span class=\"greek\">ἱερῶν</span>; Philo, Spec. Leg. 1, 221 <span class=\"greek\">κοινωνὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βωμοῦ</span>). <span class=\"greek\">τῶν</span> <span class=\"greek\">παθημάτων</span> (Diod S 4, 20, 2 <span class=\"greek\">τῶν</span> <span class=\"greek\">κακοπαθειῶν</span> <span class=\"greek\">κ</span>.), <span class=\"greek\">τῆς</span> <span class=\"greek\">παρακλήσεως</span>, dos sofrimentos e da consolação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:7</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μελλούσης</span> <span class=\"greek\">ἀποκαλύπτεσθαι</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">κ</span>., participante da glória que há de ser revelada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:1</a>. <span class=\"greek\">θείας</span> <span class=\"greek\">φύσεως</span>, da natureza divina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:4</a> (compare a inscrição da Comagena citada em <span class=\"greek\">κοινωνέω</span> 1a; sobre o tema, veja também Plut., Mor. 781a). <span class=\"greek\">τῆς</span> <span class=\"greek\">μοιχείας</span>, participante do adultério, Hm 4, 1, 5 (Socrat., Ep. 7, 1 <span class=\"greek\">κοι</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικήματος</span>; Polyaenus 2, 14, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαναστάσεως</span>, participante da revolta). <span class=\"greek\">ἀμφότεροι</span> <span class=\"greek\">κοινωνοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔργου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δικαίου</span>, ambos participantes da obra do justo, Hs 2:9 (Pla., Ep. 7, 325a <span class=\"greek\">ἀνοσίων</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">κοι</span>.).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Por <span class=\"greek\">ἐν</span>: D 4:8. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀφθάρτῳ</span> <span class=\"greek\">κ</span>., participante daquilo que é incorruptível, B 19:8.</p>\n<p class=\"entry-text\">ⓒ Com alguém em alguma coisa: <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span>, companheiros deles no sangue dos profetas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:30</a>.</p>\n<p class=\"entry-text\">ⓓ Sem complemento (4 Km 17:11): <span class=\"greek\">κ</span>. <span class=\"greek\">ἐμὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">συνεργός</span>, meu companheiro e cooperador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:23</a> (para a combinação de <span class=\"greek\">κ</span>. e <span class=\"greek\">συνεργός</span>, compare as duas primeiras passagens de Plut. citadas em b<span class=\"greek\">α</span>; também X., Mem. 2, 6, 26). <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">κοινωνόν</span>, considerar alguém como companheiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 17</a> (sobre Eva: <span class=\"greek\">κοινωνὸν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">δέχεται</span>, Did., Gen. 82, 28; compare Diod S 18, 53, 6 <span class=\"greek\">ἔσχε</span> <span class=\"greek\">κοινωνοὺς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐλπίδων</span>).</p>\n<p class=\"entry-text\">② Aquele que permite a outra pessoa participar de algo; alguém que compartilha, com <span class=\"greek\">τινί</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποκαλυφθέντων</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">γινόμεθα</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">κοινωνοί</span>, deixamos que participeis daquilo que nos foi revelado, Dg 11:8.—O sentido concreto de ‘membro’ (Idomeneus Hist. [III a.C.]: 338 Fgm. 8 Jac. <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">προαιρέσεως</span> = ‘membro do partido’) parece não ocorrer em nossa literatura.—DELG s.v. <span class=\"greek\">κοινός</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινῶς</span>, advérbio de <span class=\"greek\">κοινός</span> (Eur. e outros): na língua ou no dialeto comum (Apollon. Dysc., Pron. 82, 27 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:17</a>, variante de leitura.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοινωφελής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοινωφελής</span>, <span class=\"greek\">ές</span> (veja <span class=\"greek\">κοινός</span>, <span class=\"greek\">ὠφέλεια</span>; Epict. 4, 10, 12; M. Ant. 1, 16, 4; 3, 4, 1; 4, 12, 2; POxy 1409, 19 [III d.C.]; Philo, De Jos. 34; 73, Mos. 2, 9; 28, Spec. Leg. 4, 157; 170 e outros): útil a todos, de utilidade geral. <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσιν</span>, procurar o bem comum de todos, 1 Cl 48:6.—DELG 2 <span class=\"greek\">ὀφέλλω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοίτη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοίτη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κεῖμαι</span> e o verbete seguinte; desde Hom.; inscrições, papiros, LXX; PsSol 17:16; TestSol 2:11 D; TestReub 1:6; Joseph., SibOr; empréstimo no hebraico rabínico).</p>\n<p class=\"entry-text\">① Estrutura para deitar-se. ⓐ Em geral, cama (Cass. Dio 61, 13, 5; Herm. Wr. 1, 29; 2 Km 4:5; Jos., Ant. 6, 52 <span class=\"greek\">κοίτης</span> <span class=\"greek\">ὥρα</span>), <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἶναι</span>, estar na cama, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:7</a> (Jos., Ant. 1, 177 <span class=\"greek\">τ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">κοίταις</span> <span class=\"greek\">ὄντας</span>).</p>\n<p class=\"entry-text\">ⓑ Especialmente (autores trágicos e outros; SibOr 4, 33), leito matrimonial (com <span class=\"greek\">γάμος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:4</a> (veja 2a abaixo; sobre a ‘contaminação’ do leito matrimonial pelo adultério, compare Ps.-Plut., Fluv. 8, 3 e Jos., Ant. 2, 55 <span class=\"greek\">τ</span>. <span class=\"greek\">κοίτην</span> <span class=\"greek\">μιαίνειν</span>; Artem. 2, 26; Synes., Dreams 11 p. 143b <span class=\"greek\">κοίτην</span> <span class=\"greek\">ἀμόλυντον</span>; Gen 49:4; TestReub 1:6).—<span class=\"greek\">τράπεζαν</span> <span class=\"greek\">κοινὴν</span> <span class=\"greek\">παρατίθενται</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">κοιτήν</span>, põem à disposição uma mesa comum, mas não um leito (para relações sexuais), Dg 5:7 (conjectura para <span class=\"greek\">κοινήν</span>; veja Bihlmeyer, margem).</p>\n<p class=\"entry-text\">② Envolvimento em relações sexuais, extensão figurada do sentido 1. ⓐ Relação sexual (Eur., Med. 152, Alc. 249; Lev 15:21–26; Wsd 3:13, 16); no plural (com <span class=\"greek\">ἀσέλγειαι</span>), excessos sexuais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:13</a>. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:4</a>.</p>\n<p class=\"entry-text\">ⓑ Emissão seminal (Num 5:20 <span class=\"greek\">ἔδωκέν</span> <span class=\"greek\">τις</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κοίτην</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σοί</span>. Na expressão completa <span class=\"greek\">κοίτη</span> <span class=\"greek\">σπέρματος</span>: Lev 15:16f, 32; 18:20; 22:4), <span class=\"greek\">κοίτην</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑνός</span>, conceber filhos de um só homem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:10</a>. <span class=\"greek\">κοίτη</span> <span class=\"greek\">κοινή</span>, promiscuidade sexual, Dg 5:7, conjectura.—B. 480. DELG s.v. <span class=\"greek\">κεῖμαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοιτών, ῶνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοιτών</span>, <span class=\"greek\">ῶνος</span>, <span class=\"greek\">ὁ</span> (veja o verbete precedente; esta palavra, rejeitada pelos aticistas [Phryn. p. 252 Lob.], encontra-se em Diod S 11, 69, 2; Epict. e outros; inscrições, papiros, LXX; TestAbr B 6 p. 110, 4 [Stone p. 68]; JosAs 25:1, códice A, em lugar de <span class=\"greek\">θάλαμος</span>; Jos., Vi. 382; TestReub 3:13; empréstimo no hebraico rabínico): dormitório, quarto de dormir; empregada como parte de um título: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοιτῶνος</span>, o responsável pela câmara de dormir, o camareiro (Epict. 4, 7, 1; OGI 256, 5 [cerca de 130 a.C.] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κοιτῶνος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλίσσης</span>. Outros exemplos em Magie 73), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:20</a>; AcPl Ha 5, 21; 32; GJs 6:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἁγιάσματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. e <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγιάσματος</span>, 6:3 (veja <span class=\"greek\">ἁγίασμα</span>).—DELG s.v. <span class=\"greek\">κεῖμαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοκκάριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοκκάριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Rufus [II d.C.] em Oribasius 8, 47, 11): diminutivo de <span class=\"greek\">κόκκος</span>; pequeno grão de granizo, Hm 11:20.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόκκινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόκκινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (veja o verbete seguinte; Herodas 6, 19; Martial 2, 39; Plut., Fab. 15, 1; Epict.; PHamb 10, 24; PLond II, 191, 5 p. 264 [103–17 d.C.]; 193 verso, 22 p. 246 [II d.C.]; LXX [sobre a terminologia hebraica subjacente, veja Gradwohl, abaixo, 73]; ParJer 9:18; Philo; Jos., Ant. 8, 72, variante de leitura; Just., D. 46, 5): vermelho, escarlate. <span class=\"greek\">χλαμὺς</span> <span class=\"greek\">κ</span>., manto vermelho do ‘sagum purpureum (paludamentum)’ dos soldados romanos, vestimenta de tingimento barato em contraste com os caros trajes ‘púrpura’ (compare Gradwohl 73–75; WBorn, Scarlet: CIBA Review 7, ’38, 206–27; GFaber, Dyeing in Greece, ibid. 284; LJensen, JNES 22, ’63, 111), cujas tonalidades derivavam de moluscos e eram usadas pelas classes superiores (veja <span class=\"greek\">πορφυροῦς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:28</a>; <span class=\"greek\">ἔριον</span> <span class=\"greek\">κ</span>., lã escarlate, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:19</a>; B 7:8ff, 11; 8:1. Como cor de uma besta apocalíptica ou de sua cobertura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:3</a>.—<span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>., tecido escarlate, veste escarlate (Epict. 3, 22, 10 <span class=\"greek\">ἐν</span> <span class=\"greek\">κοκκίνοις</span> <span class=\"greek\">περιπατεῖν</span>; 4, 11, 34; 2 Km 1:24.—Gen 38:28; Ex 25:4; Josh 2:18; 2 Ch 2:13): <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">περιβεβλημένη</span> <span class=\"greek\">πορφυροῦν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κόκκινον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a>; compare 18:16 (os tecidos eram tingidos de diversas maneiras; <span class=\"greek\">πορφ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">κόκκ</span>.; compare PTebt 405, 5; Ex 39:12; 2 Ch 2:6), v. 12; GJs 10:1 (três vezes); 12:1f; (em oposição a <span class=\"greek\">ἔριον</span>, ‘lã branca’) 1 Cl 8:4 (Is 1:18); cordão escarlate, 12:7.—EWunderlich, Die Bed. der roten Farbe im Kultus der Griechen u. Römer 1925; RGradwohl, D. Farben im AT, Beih. ZAW 83, ’63, 73–78. ABD, artigo ‘Purple’ (bibliografia).—DELG s.v. <span class=\"greek\">κόκκος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόκκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόκκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja o verbete precedente; Hom. Hymns, Hdt. e outros; Lam 4:5 ‘púrpura [vestimentas]’; TestSol 18:33; JosAs 16:13 códice A; SIG 1173, 12; PGM 7, 638): genericamente, ‘grão, semente’.</p>\n<p class=\"entry-text\">① Núcleo de várias plantas, semente, grão: de mostarda, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:31</a>; 17:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:19</a>; 17:6; de trigo etc. (Favorinus [começo do II d.C.] em Diog. L. 6, 88), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a> (Ocellus [II a.C.] c. 16 H.: a <span class=\"greek\">ἀνάλυσις</span> do fruto liberta a semente; compare Philo, Aet. M. 94ff); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:37</a> (HRiesenfeld, TU 77, ’61, 43–55; sobre a imagem, veja Straub 70–72).</p>\n<p class=\"entry-text\">② Antigamente considerado uma baga, o quermes é um inseto fêmea com escamas (semelhante à cochonilha), que se prende às folhas de um carvalho. Os corpos secos desses insetos eram utilizados pelos antigos para preparar uma tintura vermelho-púrpura (veja Theophr., HP 3, 7, 3; 3, 16, 1; Gradwohl [veja o fim de <span class=\"greek\">κόκκινος</span>] 73–78; WBorn, Scarlet: CIBA Review 7, ’38, 206–14). Por metonímia, <span class=\"greek\">κ</span>. passou a designar tanto a cor (‘escarlate’) quanto o tecido tratado com a tintura (Dromo Com. [IV a.C.] Fgm. 1, 4 Kock [em Athen. 6, 240d]; PHolm 22, 1; Sir 45:10; Jos., Bell. 6, 390): escarlate (cor), 1 Cl 8:3 (citação de origem desconhecida; aqui provavelmente se refere a tecido tingido de púrpura [compare Lam 4:5] em razão do <span class=\"greek\">σάκκος</span> correspondente).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0205-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοκκύζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοκκύζω</span> (<span class=\"greek\">κόκκυ</span>, ‘o canto do galo’; Hes. e outros; TestSol 9:3 C): cantar, dito de um galo (Cratinus e outros; Plato Com. [V/IV a.C.] 209 p. 659 K.; Hyperid., Fgm. 239), em fragmento evangélico proveniente de Fayum, com texto restaurado (Kl. T. 83, p. 23, 10 = Otero [segundo Harnack] I 85 Fgm. linha 7 [bibliografia] = ASyn. 315, 53; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:30</a>).—DELG s.v. <span class=\"greek\">κόκκυ</span>.</p></section></article>"};
